import copyIconUrl from '../icons/content_copy.svg?url';

/* Debug console — always active, opened via the Debug Log button in the help view */
(function () {
  const logs = [];

  function formatArg(a) {
    try { return typeof a === 'object' && a !== null ? JSON.stringify(a) : String(a); }
    catch { return '[unserializable]'; }
  }

  function addLog(level, text) {
    const ts = new Date().toISOString().slice(11, 23);
    logs.push({ level, text, ts });
    if (logListEl) appendEntry(level, text, ts);
  }

  ['log', 'warn', 'error'].forEach(level => {
    const orig = console[level];
    console[level] = (...args) => {
      orig.apply(console, args);
      addLog(level, args.map(formatArg).join(' '));
    };
  });

  window.addEventListener('unhandledrejection', e => {
    addLog('error', `Unhandled rejection: ${e.reason?.stack || e.reason}`);
  });

  window.addEventListener('error', e => {
    addLog('error', `Uncaught: ${e.message} (${e.filename}:${e.lineno}:${e.colno})`);
  });

  let logListEl = null;

  function appendEntry(level, text, ts) {
    const el = document.createElement('div');
    el.className = `dbg-entry dbg-entry-${level}`;
    el.textContent = `${ts} [${level}] ${text}`;
    logListEl.appendChild(el);
    logListEl.scrollTop = logListEl.scrollHeight;
  }

  function createUI() {
    const style = document.createElement('style');
    style.textContent = `
      #dbg-pane {
        position: fixed;
        top: 40px;
        left: 40px;
        right: 40px;
        bottom: 40px;
        z-index: 9999;
        background: #111;
        color: #ddd;
        border: 1px solid #444;
        border-radius: 8px;
        display: flex;
        flex-direction: column;
        font-family: monospace;
        font-size: 11px;
      }
      #dbg-pane.dbg-hidden { display: none; }
      #dbg-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 8px 12px;
        border-bottom: 1px solid #333;
        flex-shrink: 0;
      }
      #dbg-header span { font-weight: bold; color: #aaa; }
      #dbg-copy, #dbg-close {
        background: none;
        border: none;
        cursor: pointer;
        padding: 2px;
        display: flex;
        align-items: center;
      }
      #dbg-copy img { width: 18px; height: 18px; filter: invert(1); }
      #dbg-close { color: #aaa; font-size: 16px; line-height: 1; }
      #dbg-close:hover { color: #fff; }
      #dbg-log-list {
        overflow-y: auto;
        flex: 1;
        padding: 8px 12px;
        white-space: pre-wrap;
        word-break: break-all;
      }
      #dbg-toggle {
        position: fixed;
        bottom: 16px;
        right: 16px;
        z-index: 9998;
        background: #cc0000;
        color: #fff;
        border: none;
        border-radius: 6px;
        padding: 6px 12px;
        font-size: 12px;
        cursor: pointer;
      }
      .dbg-entry { margin-bottom: 2px; line-height: 1.4; }
      .dbg-entry-log { color: #ccc; }
      .dbg-entry-warn { color: #f0c040; }
      .dbg-entry-error { color: #ff6b6b; }
    `;
    document.head.appendChild(style);

    const pane = document.createElement('div');
    pane.id = 'dbg-pane';
    pane.classList.add('dbg-hidden');

    const header = document.createElement('div');
    header.id = 'dbg-header';

    const title = document.createElement('span');
    title.textContent = 'Console';

    const copyBtn = document.createElement('button');
    copyBtn.id = 'dbg-copy';
    copyBtn.title = 'Copy to clipboard';
    const copyImg = document.createElement('img');
    copyImg.src = copyIconUrl;
    copyBtn.appendChild(copyImg);

    const closeBtn = document.createElement('button');
    closeBtn.id = 'dbg-close';
    closeBtn.title = 'Close';
    closeBtn.textContent = '✕';

    header.appendChild(title);
    header.appendChild(copyBtn);
    header.appendChild(closeBtn);

    logListEl = document.createElement('div');
    logListEl.id = 'dbg-log-list';

    pane.appendChild(header);
    pane.appendChild(logListEl);
    document.body.appendChild(pane);

    function togglePane() {
      const hidden = pane.classList.toggle('dbg-hidden');
      if (!hidden) {
        logListEl.innerHTML = '';
        logs.forEach(({ level, text, ts }) => appendEntry(level, text, ts));
      }
    }

    document.getElementById('dbg-toggle-help').addEventListener('click', togglePane);

    closeBtn.addEventListener('click', () => pane.classList.add('dbg-hidden'));

    if (new URLSearchParams(location.search).get('debug') === 'true') {
      const floatBtn = document.createElement('button');
      floatBtn.id = 'dbg-toggle';
      floatBtn.textContent = 'DEBUG';
      floatBtn.addEventListener('click', togglePane);
      document.body.appendChild(floatBtn);
    }

    document.getElementById('help-build-date').textContent = `Built: ${__BUILD_DATE__}`;

    copyBtn.addEventListener('click', () => {
      const text = logs.map(({ level, text, ts }) => `${ts} [${level}] ${text}`).join('\n');
      navigator.clipboard.writeText(text).catch(() => {
        const ta = document.createElement('textarea');
        ta.value = text;
        ta.style.position = 'fixed';
        ta.style.opacity = '0';
        document.body.appendChild(ta);
        ta.select();
        document.execCommand('copy');
        document.body.removeChild(ta);
      });
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', createUI);
  } else {
    createUI();
  }
})();
