// Utility functions shared across the application

import moment from 'moment';

export function isValidNumber(val) {
  return typeof val !== 'undefined' && val != null && !isNaN(parseFloat(val)) && isFinite(val);
}

export function shortTimeFormat(seconds) {
    const absTime = Math.abs(seconds);
    const hours = Math.floor(absTime / 3600);
    const mins = Math.floor((absTime % 3600) / 60);
    const secs = absTime % 60;

    let result = seconds < 0 ? "-" : "";
    if (hours > 0) {
        result += `${hours}h${mins}m`;
    } else if (mins > 0) {
        result += `${mins}m${secs}s`;
    } else {
        result += `${secs}s`;
    }
    return result;
}

export function stringifyWithMaxDepth(obj, maxDepth = 2, space = 2) {

  function replacer(key, value) {
    const depth = this.__depth__ || 0

    if (typeof value === 'object' && value !== null) {
      if (!value.__depth__) {
        // Attach depth to nested objects
        Object.defineProperty(value, '__depth__', {
          value: depth + 1,
          enumerable: false,
        })
      }
      if (depth >= maxDepth) {
        return { __inline__: JSON.stringify(value) }
      }
    }

    return value
  }

  // First stringify using our depth-aware replacer
  const raw = JSON.stringify(obj, replacer, space)

  // Then clean up: replace { "__inline__": "..." } with the raw JSON
  const result = raw.replace(
    /{\s*"__inline__"\s*:\s*"((?:[^"\\]|\\.)*)"\s*}/g,
    (_, inner) => {
      const unescaped = inner
        .replace(/\\"/g, '"') // remove escaped quotes
        .replace(/\\\\/g, '\\') // remove double backslashes
      return unescaped
    }
  )

  return result
}


export function formatDate(date, format = 'YYYY-MM-DD HH:mm:ss') {
  return moment(date).format(format);
}


export function toISO8601(date) {
  return moment(date).toISOString();
}

let _toastTimeoutId = null;

export function showToast(message) {
  let toast = document.getElementById('sharedToast');
  if (!toast) {
    toast = document.createElement('div');
    toast.id = 'sharedToast';
    toast.className = 'toast';
    document.body.appendChild(toast);
  }
  if (_toastTimeoutId) {
    clearTimeout(_toastTimeoutId);
    _toastTimeoutId = null;
  }
  toast.textContent = message;
  toast.style.display = 'block';
  _toastTimeoutId = setTimeout(() => {
    toast.style.display = 'none';
    _toastTimeoutId = null;
  }, 3000);
}

export function notifyError(message, e) {
  console.log(message,e);
  showToast(message,e?.message);
}